/**
 * Pre-launch / kickstarter framing: the single source of truth for the launch
 * copy that appears across the announcement bar, pricing, founders page, and
 * manifesto. Maester Cloud is being built in the open; subscribing before GA
 * funds development and makes you a Founding Supporter.
 */

/** Private preview opens ahead of GA. */
export const previewMonth = 'August 2026';

/** The GA target. Soft framing: a target, not a hard ship date. */
export const launchMonth = 'September 2026';

/** Short status line for banners and headers. */
export const launchStatus = `In active development · private preview ${previewMonth} · general availability targeted for ${launchMonth}`;

/** One-liner used in CTAs and cards. */
export const foundingBlurb =
  'Subscribe before launch to become a Founding Supporter. You fund keeping the Maester core open and free for everyone, and you get a place on the Founding Supporters wall for you or your organization.';

/** The launch-notify capture endpoint (proxied to the signup API in dev). */
export const notifyEndpoint = '/api/notify';
